// Builds the images-at-drawn-size arm (task image-audit) from one audit file of the rewrite, and checks it.
//   node src/images/cli.mjs arm build --audit images-chromium-rewrite.json [--out apps/site/public/images-drawn] [--manifest drawn.json]
//   node src/images/cli.mjs arm check [--manifest drawn.json] [--out apps/site/public/images-drawn]
// The table (apps/site/src/flags/images/drawn.json) and the copies (apps/site/public/images-drawn/**) are GENERATED by this
// command: never edit them by hand. Resizing uses macOS `sips`, so a build runs on a Mac; the copies are committed, and CI only
// serves and checks them (the manifest records the sha256 of every copy and of every source).
//
// What a copy is. For every image of the lag regions (hero, morph, people) that the audit saw drawn, the device pixels it needs
// at a page width w and DPR d are ceil(css size * max(1, its largest visual scale) * d). The copy is the smallest rung of a
// geometric ladder (x1.5, multiples of 8) that holds those pixels at the image's own aspect ratio; a rung at 90 % of the
// natural width or more leaves the image alone (no copy, null in the table). Layout does not depend on DPR, so one audit at one
// DPR gives the sizes of all three.
//
// Premises (INFERRED, checked by the verify command and the drawn-arm audit on CI):
//   P1 an image's drawn CSS size is the same for the copy as for the source (the copy has the source's aspect ratio, so only a
//      size taken from the natural size would move; the drawn-arm audit compares every box and drawn size with the rewrite's);
//   P2 between two audit widths that are more than 1 px apart the layout grows with the width, so a row is sized by the larger of
//      its own probe and the next one (two probes 1 px apart bracket a breakpoint edge, and the row ends there).
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { siteDist } from '../serve.mjs';
import { DEFAULT_MANIFEST, fileUnder } from './arm.mjs';
import { regionOf, LAG_REGIONS, sniff } from './reduce.mjs';

export const DPRS = [2, 3];
export const LADDER_RATIO = 1.5;
export const KEEP_AT = 0.9;
export const LADDER = (() => {
  const out = [];
  for (let w = 64; w < 8192; w *= LADDER_RATIO) { const r = Math.round(w / 8) * 8; if (out[out.length - 1] !== r) out.push(r); }
  return out;
})();

/** Smallest rung holding `need` device pixels of width, or Infinity (keep the source) when the rung would be >= KEEP_AT of the natural width. */
export function rungFor(need, natW) {
  const r = LADDER.find((x) => x >= need);
  if (r === undefined || r >= natW * KEEP_AT) return Infinity;
  return r;
}

/** Device width a copy needs: the drawn size at the source's aspect, scaled by the largest visual scale and the DPR. */
export function needW(cssW, cssH, natW, natH, scale, dpr) {
  return Math.ceil(Math.max(cssW, (cssH * natW) / natH) * scale * dpr);
}

/** The served path of the copy of `url` at rung `w`: /images-drawn/<path>-<w>.<ext>. */
export function copyPath(url, w) {
  const m = /^(.*)\.([A-Za-z0-9]+)$/.exec(url.split('?')[0]);
  if (!m) throw new Error(`no extension: ${url}`);
  return `/images-drawn${m[1]}-${w}.${m[2].toLowerCase()}`;
}

/** Per-image requirement at each audited width: { url -> { nat, widths: [{w, cssW, cssH, scale}] } } from one audit file. */
export function requirements(file) {
  const by = new Map();
  for (const [key, c] of Object.entries(file.cells)) {
    if (c.error) continue;
    for (const it of c.items) {
      if (it.none) continue;
      if (!LAG_REGIONS.includes(regionOf(it))) continue;
      if (/^data:/.test(it.url) || it.nat[0] === 0 || it.nat[1] === 0) continue;
      const a = by.get(it.url) ?? { url: it.url, nat: it.nat, bg: it.kind === 'bg', fit: new Set(), cells: new Map() };
      a.fit.add(it.fit);
      const cell = a.cells.get(c.width) ?? { cssW: 0, cssH: 0, scale: 1 };
      cell.cssW = Math.max(cell.cssW, it.img[0]);
      cell.cssH = Math.max(cell.cssH, it.img[1]);
      cell.scale = Math.max(cell.scale, it.visMax ?? it.vis ?? 1, 1);
      a.cells.set(c.width, cell);
      by.set(it.url, a);
    }
  }
  return by;
}

/** Rows of one image at one DPR from its per-width needs (see P2). Returns [{from, w}] (w null = keep the source). */
export function rowsFor(req, widths, dpr) {
  const per = widths.map((w) => {
    const c = req.cells.get(w);
    if (!c) return 0;
    return rungFor(needW(c.cssW, c.cssH, req.nat[0], req.nat[1], c.scale, dpr), req.nat[0]);
  });
  const eff = per.map((r, i) => (i + 1 < widths.length && widths[i + 1] - widths[i] > 1 ? Math.max(r, per[i + 1]) : r));
  const rows = [];
  widths.forEach((w, i) => {
    const r = eff[i] === 0 ? LADDER[0] : eff[i];
    const cur = Number.isFinite(r) ? r : null;
    if (rows.length === 0 || rows[rows.length - 1].w !== cur) rows.push({ from: rows.length === 0 ? 0 : w, w: cur });
  });
  return rows;
}

const sha = (buf) => createHash('sha256').update(buf).digest('hex');

/**
 * Resize one source with sips. Same format as the source; JPEG quality 92. A PNG goes on through pngquant (256-colour palette,
 * Homebrew `pngquant`): the Fastwork PNGs are palette files and sips writes 32-bit RGBA, which would be 2 to 3 times the bytes.
 */
export function resize(srcAbs, dstAbs, w, h, format) {
  mkdirSync(dirname(dstAbs), { recursive: true });
  const args = ['-s', 'format', format];
  if (format === 'jpeg') args.push('-s', 'formatOptions', '92');
  execFileSync('sips', [...args, '--resampleHeightWidth', String(h), String(w), srcAbs, '--out', dstAbs], { stdio: ['ignore', 'ignore', 'pipe'] });
  if (format === 'png') execFileSync('pngquant', ['--force', '--speed', '1', '--output', dstAbs, '256', dstAbs], { stdio: ['ignore', 'ignore', 'pipe'] });
}

export function build({ audit, out, manifest, srcRoot = siteDist(), publicRoot }) {
  const file = JSON.parse(readFileSync(audit, 'utf8'));
  if (file.schema !== 'fw.images.audit/1') throw new Error(`${audit}: schema ${file.schema}`);
  const widths = [...new Set(Object.values(file.cells).filter((c) => !c.error).map((c) => c.width))].sort((a, b) => a - b);
  const reqs = requirements(file);
  const m = {
    schema: 'fw.images.drawn/1',
    generated: 'node packages/gate-breakpoints/src/images/cli.mjs arm build (GENERATED, do not edit by hand)',
    audit: { engine: file.engine, version: file.version, arm: file.arm, widths },
    ladder: { ratio: LADDER_RATIO, keepAt: KEEP_AT, rungs: LADDER },
    images: {},
    skipped: {},
  };
  const todo = new Map();
  for (const req of [...reqs.values()].sort((a, b) => a.url.localeCompare(b.url))) {
    const srcAbs = join(srcRoot, req.url.replace(/^\//, ''));
    if (!existsSync(srcAbs)) { m.skipped[req.url] = 'source not found'; continue; }
    const buf = readFileSync(srcAbs);
    const fmt = sniff(buf.subarray(0, 600));
    if (fmt !== 'jpeg' && fmt !== 'png') { m.skipped[req.url] = `format ${fmt}`; continue; }
    // a size taken from the natural size (background-size auto, object-fit none / scale-down) would move with the copy
    if ([...req.fit].some((f) => f === 'none' || f === 'scale-down' || /(^|\s)auto(\s|$)/.test(f))) { m.skipped[req.url] = 'size from the natural size'; continue; }
    const dprs = {};
    for (const d of DPRS) {
      const rows = rowsFor(req, widths, d);
      if (rows.every((r) => r.w === null)) continue;
      dprs[String(d)] = rows.map((r) => ({ from: r.from, file: r.w === null ? null : copyPath(req.url, r.w), w: r.w }));
      for (const r of rows) if (r.w !== null) todo.set(copyPath(req.url, r.w), { url: req.url, w: r.w, fmt, srcAbs });
    }
    if (Object.keys(dprs).length === 0) { m.skipped[req.url] = 'needs the natural size'; continue; }
    m.images[req.url] = { nat: req.nat, format: fmt, srcSha256: sha(buf), srcBytes: buf.length, dprs };
  }
  const files = {};
  for (const [path, t] of [...todo.entries()].sort()) {
    const natH = m.images[t.url].nat[1];
    const natW = m.images[t.url].nat[0];
    const h = Math.max(1, Math.round((natH * t.w) / natW));
    const dst = fileUnder(out, path.replace(/^\/images-drawn\//, ''));
    resize(t.srcAbs, dst, t.w, h, t.fmt);
    const buf = readFileSync(dst);
    files[path] = { w: t.w, h, bytes: buf.length, sha256: sha(buf) };
  }
  m.files = files;
  mkdirSync(dirname(manifest), { recursive: true });
  writeFileSync(manifest, JSON.stringify(m, null, 1) + '\n');
  const srcBytes = Object.values(m.images).reduce((s, e) => s + e.srcBytes, 0);
  const copyBytes = Object.values(files).reduce((s, f) => s + f.bytes, 0);
  return { images: Object.keys(m.images).length, skipped: Object.keys(m.skipped).length, files: Object.keys(files).length, copyBytes, srcBytes, manifest };
}

/** Check the table against the files (all present, sizes and hashes as recorded) and against the sources (hashes as recorded). */
export function check({ manifest, out, srcRoot = siteDist(), withSources = true }) {
  const m = JSON.parse(readFileSync(manifest, 'utf8'));
  const bad = [];
  for (const [path, f] of Object.entries(m.files)) {
    const abs = fileUnder(out, path.replace(/^\/images-drawn\//, ''));
    if (!existsSync(abs)) { bad.push(`${path}: missing`); continue; }
    const buf = readFileSync(abs);
    if (buf.length !== f.bytes || sha(buf) !== f.sha256) bad.push(`${path}: differs from the table`);
  }
  for (const [url, e] of Object.entries(m.images)) {
    for (const rows of Object.values(e.dprs)) for (const r of rows) if (r.file && !m.files[r.file]) bad.push(`${url}: ${r.file} not in files`);
    if (!withSources) continue;
    const abs = join(srcRoot, url.replace(/^\//, ''));
    if (!existsSync(abs)) { bad.push(`${url}: source missing`); continue; }
    if (sha(readFileSync(abs)) !== e.srcSha256) bad.push(`${url}: source changed`);
  }
  return { files: Object.keys(m.files).length, images: Object.keys(m.images).length, bad };
}

export async function armCli(args, { arg, list }) {
  const sub = args[0];
  const repo = resolve(dirname(DEFAULT_MANIFEST), '../../../../..');
  const out = resolve(arg('out', join(repo, 'apps/site/public/images-drawn')));
  const manifest = resolve(arg('manifest', DEFAULT_MANIFEST));
  if (sub === 'build') {
    const r = build({ audit: resolve(arg('audit')), out, manifest, srcRoot: arg('src') ? resolve(arg('src')) : siteDist() });
    console.log(JSON.stringify(r));
    return;
  }
  if (sub === 'check') {
    const r = check({ manifest, out, srcRoot: arg('src') ? resolve(arg('src')) : siteDist(), withSources: !args.includes('--no-sources') });
    console.log(`arm check: ${r.images} images, ${r.files} files, ${r.bad.length} problems`);
    for (const b of r.bad.slice(0, 20)) console.log(`  ${b}`);
    if (r.bad.length) process.exit(1);
    return;
  }
  if (sub === 'verify') {
    const { verifyCli } = await import('./verify.mjs');
    await verifyCli(args.slice(1), { arg, list });
    return;
  }
  if (sub === 'pages') {
    const { pagesCli } = await import('./pages.mjs');
    await pagesCli(args.slice(1), { arg, list });
    return;
  }
  console.error('usage: arm build|check|verify|pages');
  process.exit(2);
}
